// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface IncidentDetailOut {
  incident_id: number;
  incident_number: string;
  type_code: string;
  type_name: string;
  area: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational";
  kind: "Incident" | "NearMiss";
  harm: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death";
  is_sentinel: boolean;
  /** Why the Quality Officer classed it otherwise than the list */
  sentinel_override: string | null;
  occurred_at: string;
  department_id: number | null;
  department_name: string | null;
  ward_id: number | null;
  ward_name: string | null;
  location: string | null;
  affected: "Patient" | "Staff" | "Visitor" | "None";
  patient_id: number | null;
  mrn: string | null;
  patient_name: string | null;
  admission_id: number | null;
  admission_number: string | null;
  employee_id: number | null;
  employee_name: string | null;
  booking_id: number | null;
  booking_number: string | null;
  procedure_name: string | null;
  ot_phase: "BeforeInduction" | "Induction" | "Maintenance" | "Emergence" | "Recovery" | "AfterRecovery" | null;
  drug_id: number | null;
  drug_name: string | null;
  medication_stage: "Prescribing" | "Transcribing" | "Dispensing" | "Administration" | "Monitoring" | null;
  /** The medicine is on the high-alert list (MSDS CQI 102 iv) */
  high_alert: boolean;
  death_id: number | null;
  death_number: string | null;
  description: string;
  immediate_action: string;
  screening_key: string | null;
  reporter_confidential: boolean;
  /** Null when the reporter asked for confidentiality (shown to the managers only) */
  reported_by: number | null;
  reported_by_name: string;
  reported_at: string;
  report_stamp: AuthorStampOut | null;
  status: "Reported" | "UnderReview" | "Analysed" | "Closed" | "Withdrawn";
  reviewed_at: string | null;
  reviewed_by_name: string | null;
  review_note: string | null;
  investigator_user_id: number | null;
  investigator_name: string | null;
  analysis_due: string | null;
  withdraw_reason: string | null;
  analysis_method: "Review" | "RootCauseAnalysis" | null;
  chronology: string | null;
  root_causes: string | null;
  contributing_factors: string[];
  lessons: string | null;
  disclosure: "Disclosed" | "NotYet" | "NotApplicable" | null;
  disclosure_note: string | null;
  external_reference: string | null;
  analysed_at: string | null;
  analysis_stamp: AuthorStampOut | null;
  closure_note: string | null;
  closed_at: string | null;
  closure_stamp: AuthorStampOut | null;
  row_version: number;
  /** Reported and still not reviewed after incident_review_hours */
  review_overdue: boolean;
  analysis_overdue: boolean;
  actions: QualityActionOut[];
  /** What happens next; null when closed or withdrawn */
  next_step: string | null;
  can_review: boolean;
  can_withdraw: boolean;
  /** The caller may save and sign the analysis (the investigator or a manager) */
  can_analyse: boolean;
  can_add_action: boolean;
  can_close: boolean;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

/** One incident — GET /api/v1/incidents/{incident_id} (who may call: incident.view, the reporter and the investigator; ot.clinical_statistics.view for theatre adverse events). */
export function getIncident(incident_id: number): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("GET", `/incidents/${incident_id}`, undefined);
}
